import{_ as l,l as s,o as e,c as i,v as o,p as d,x as r,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"标量替换 SROA","description":"","frontmatter":{"title":"标量替换 SROA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sroa.md","filePath":"cs/sroa.md","lastUpdated":1789023840000}'),A={name:"cs/sroa.md"};function S(h,a,_,m,u,f){const t=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="标量替换-sroa" tabindex="-1">标量替换 SROA <a class="header-anchor" href="#标量替换-sroa" aria-label="Permalink to &quot;标量替换 SROA&quot;">​</a></h1><div class="epigraph"><p>把不逃逸的结构体或数组拆成成员标量，用 SSA 名代替内存槽，使后续传播与分配看见寄存器，而不是 load/store。</p><footer>—— 据 Cytron 等标量替换思想；LLVM SROA；Appel 对聚合的讨论整理</footer></div><p>上一课<a href="/cs/escape-analysis">逃逸分析</a>标出未逃逸对象。缺口是<strong>拆开</strong>：<code>struct {int a,b;}</code> 的 <code>p.a</code> 不应经过栈槽。SROA（scalar replacement of aggregates）：按偏移切成元素，能提升则变 <code>alloca</code> 上的 SSA。本课钉切分条件，不写完整 mem2reg 与 φ 插入——SSA 构造后课。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 <code>alloca</code>：若只被常量偏移的 load/store 访问、无变长索引、指针不逃逸，则每个槽一个名。数组常下标则整数组可能无法拆。选择：拆字段，留无法拆的部分在内存。</p><h3 id="sroa-不是寄存器分配" tabindex="-1">SROA 不是寄存器分配 <a class="header-anchor" href="#sroa-不是寄存器分配" aria-label="Permalink to &quot;SROA 不是寄存器分配&quot;">​</a></h3><p>拆完是虚拟寄存器；着色后课。不要声称 SROA 已选物理寄存器。</p><p><span class="marginnote">LLVM 的 SROA/mem2reg 是工程标准名。Muchnick 有标量替换。与 SSA 构造紧密：提升后的名要插 φ。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>聚合在 IR 里常是内存，阻塞 GVN 与常量传播。提升后 <code>s.a=1; use(s.a)</code> 变成常量。缺口是<strong>可拆形状</strong>，不是逃逸分类本身。</p>',10)),(e(),d(p,null,{default:r(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20AGG%5B%22alloca%20%E8%81%9A%E5%90%88%22%5D%20--%3E%20SPLIT%5B%22%E6%8C%89%E5%AD%97%E6%AE%B5%E5%88%87%E5%BC%80%22%5D%0A%20%20SPLIT%20--%3E%20SSA%5B%22%E6%8F%90%E5%8D%87%E4%B8%BA%20SSA%20%E5%90%8D%22%5D%0A%20%20SSA%20--%3E%20OPT%5B%22%E4%BC%A0%E6%92%AD%20%2F%20DCE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与 ABI：参数结构体可能 already 在寄存器；SROA 处理的是局部槽。返回结构体由调用约定课再谈。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>选择字段：union、指针算术、可变下标使切分失败。必须保守留内存。不要拆 <code>volatile</code> 槽。</p><p>内联后新 <code>alloca</code> 是 SROA 的主要客户——与内联顺序绑在一起。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Cytron φ 放置。后课默认：未逃逸聚合可标量化。下一课 PRE：部分冗余，在标量 IR 上更有效。</p><p>也不把 SROA 当对象布局 ABI 的改变（公开结构体布局仍由语言定）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SROA：未逃逸聚合 → 成员标量 SSA。</li><li>变下标、逃逸、volatile 阻止拆分。</li><li>为传播与分配打开门，本身不着色。</li><li>出处：LLVM SROA；对照 Cytron SSA、Appel、Muchnick。</li></ul>',9))])}const T=l(A,[["render",S]]);export{R as __pageData,T as default};
